from typing import *
from typing import List
import re

def parse_music(music_string: str) -> List[int]:
    # Define the sequences and their corresponding beats
    note_sequences = {
        'o o|': 4,  # Whole note
        'o|': 2,    # Half note
        '.|': 1    # Quarter note
    }

    # Split the input string by the sequence separator
    notes = re.split(r'[\s,]+', music_string)

    # Count the number of each type of note
    note_counts = {}
    for note in notes:
        for note_type, beat in note_sequences.items():
            if note_type in note_counts:
                note_counts[note_type] += beat
            else:
                note_counts[note_type] = beat

    # Form the result list
    result = []
    for note_type, count in note_counts.items():
        result.append(count)

    return result
