def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    if n <= 0:
        return "Input must be a positive integer."
    elif n == 1:
        return 2
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 13
    elif n == 5:
        return 89

    # Check if the number is a prime Fibonacci number
    def is_prime(num: int) -> bool:
        if num <= 3:
            return num > 1
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    # Generate Fibonacci numbers up to n
    gen = (2, 1)
    while True:
        fib_current = gen[0] + gen[1]
        if fib_current > n:
            if is_prime(fib_current):
                return fib_current
            else:
                break
        gen = (gen[1], fib_current)
