def search(lst):
    frequency = {}
    for num in lst:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_count = 0
    max_num = -1
    for num, count in frequency.items():
        if count >= num and count > max_count:
            max_count = count
            max_num = num

    if max_num != -1:
        return max_num
    else:
        return -1
