def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Initialize an empty dictionary to store the letter and its count
    result = {}

    # Split the input string into individual letters
    letters = test.split()

    # Iterate through each letter in the list
    for letter in letters:
        # If the letter is already in the dictionary, update its count
        if letter in result:
            result[letter] += 1
        # If the letter is not in the dictionary, add it with a count of 1
        else:
            result[letter] = 1

    # Find the letter with the maximum count
    max_count = max(result.values())

    # Return the letter and its count as a dictionary
    return result, max_count

