def tri(n):
    if n < 1:
        return []

    # Initialize the first three numbers of the sequence
    fib_sequence = [0, 0, 1]

    # Calculate subsequent numbers using the recurrence relation
    for i in range(3, n + 1):
        if i % 2 == 0:
            fib_sequence.append(fib_sequence[i - 1] + fib_sequence[i - 2])
        else:
            fib_sequence.append(fib_sequence[i - 1] + fib_sequence[i - 2] + fib_sequence[i])

    # Add the first number of the sequence
    for i in range(len(fib_sequence)):
        if i == 0:
            fib_sequence[i] = 0
        elif i == 1:
            fib_sequence[i] = 0
        else:
            fib_sequence[i] = 0

    return fib_sequence

