import re

def Strongest_Extension(class_name, extensions):
    def count_uppercase_letters(text):
        return sum(1 for char in text if char.isupper())

    def count_lowercase_letters(text):
        return sum(1 for char in text if char.islower())

    # Find all extensions that have the same strength as the class extension
    extensions_with_same_strength = [(extension, count_uppercase_letters(extension) - count_lowercase_letters(extension)) for extension in extensions]
    # Sort the extensions by strength in descending order, then by class name in ascending order
    sorted_extensions = sorted(extensions_with_same_strength, key=lambda x: (-x[1], class_name, x[0]))

    # Return the strongest extension
    return " ".join([extension[0] for extension in sorted_extensions[:1]])

# Example usage:
print(Strongest_Extension("my_class", ["AA", "Be", "CC"]))  # Output: "my_class.AA"
